// AppendZJSON appends the JSON encoding of v to dst. On error the
// returned buffer contains a partial encoding and must be discarded.
func (v *BytesCases) AppendZJSON(dst []byte) ([]byte, error) {
	dst = append(dst, '{')
	n := len(dst)
	_ = n
	{
		if len(dst) > n {
			dst = append(dst, ',')
		}
		dst = append(dst, `"data":`...)
		dst = zerojson.AppendBytesBase64(dst, []byte(v.Data))
	}
	{
		if len(dst) > n {
			dst = append(dst, ',')
		}
		dst = append(dst, `"ptr":`...)
		if v.Ptr == nil {
			dst = append(dst, "null"...)
		} else {
			dst = zerojson.AppendBytesBase64(dst, []byte(*v.Ptr))
		}
	}
	{
		if len(dst) > n {
			dst = append(dst, ',')
		}
		dst = append(dst, `"lists":`...)
		if v.Lists == nil {
			dst = append(dst, "null"...)
		} else {
			dst = append(dst, '[')
			for i := range v.Lists {
				if i > 0 {
					dst = append(dst, ',')
				}
				dst = zerojson.AppendBytesBase64(dst, []byte(v.Lists[i]))
			}
			dst = append(dst, ']')
		}
	}
	{
		if len(dst) > n {
			dst = append(dst, ',')
		}
		dst = append(dst, `"index":`...)
		if v.Index == nil {
			dst = append(dst, "null"...)
		} else {
			dst = append(dst, '{')
			first := true
			for mk, mv := range v.Index {
				if !first {
					dst = append(dst, ',')
				}
				first = false
				dst = zerojson.AppendString(dst, string(mk))
				dst = append(dst, ':')
				dst = zerojson.AppendBytesBase64(dst, []byte(mv))
			}
			dst = append(dst, '}')
		}
	}
	return append(dst, '}'), nil
}

